import CN_api from"./api.js";import CN_common from"./common.js";import CN_element from"./element.js";import CN_event from"./event.js";import CN_session from"./session.js";import{CN_base_action}from"./base_action.js";export class CN_base_view extends CN_base_action{#properties;#record={};#tab=null;get properties(){return this.#properties}get record(){return this.#record}constructor(parent_model,properties){super(parent_model);this.#properties=CN_common.clone(properties);for(var prop_name in this.#properties){const prop=this.#properties[prop_name];prop.id=[this.parent_model.unique_id,prop_name].join("-");if(!prop.type)prop.type="string";if("typeahead"==prop.type){if(!prop.typeahead)prop.typeahead={};if(!prop.typeahead.min_length)prop.typeahead.min_length=2;if(!prop.typeahead.list)prop.typeahead.list=[];if(!prop.typeahead.on_cancel){prop.typeahead.on_cancel=el=>{el.value=this.#record[el.getAttribute("name")]}}if(!prop.typeahead.on_select){prop.typeahead.on_select=el=>{this.on_change(el.getAttribute("name"))}}}if(["integer","float"].includes(prop.type)){prop.min=this.#properties.hasOwnProperty("min")?this.#properties.min:null;prop.max=this.#properties.hasOwnProperty("max")?this.#properties.max:null}if(!CN_common.is_function(prop.is_constant))prop.is_constant=()=>false;if(!CN_common.is_function(prop.is_hidden))prop.is_hidden=()=>false}}get_text(type){if("name"==type){return this.#record.hasOwnProperty("name")?this.#record.name:this.#record.hasOwnProperty("title")?this.#record.title:undefined}if("header"==type){return`${CN_common.uc_words(this.parent_model.name.singular)} Details`}if("view_parent"==type){const parent_module=this.parent_model.get_parent_module();return parent_module?`View ${CN_common.uc_words(parent_module.model.name.singular)}`:`View ${CN_common.uc_words(this.parent_model.name.singular)} List`}return super.get_text(type)}async on_load(){const promise_list=[];for(var prop_name in this.#properties){const module_prop=this.parent_model.module.properties[prop_name];const prop=this.#properties[prop_name];if("enum"==prop.type){if(CN_common.is_object(prop.enum)&&prop.enum.path){const params={select:prop.enum.select?prop.enum.select:{column:"name"},modifier:prop.enum.modifier?prop.enum.modifier:{order:"name"}};const get_enums=async()=>{const response=await CN_api.get(prop.enum.path,params);prop.enum.values=(await response.json()).reduce((list,record)=>{list.push({key:record.id,value:record.name});return list},[])};promise_list.push(get_enums())}else{let matches=module_prop?module_prop.type.match(/^enum\('(.+)'\)$/):null;if(null==matches){throw new Error(`Property ${prop_name} has no valid enum values.`)}else{prop.enum={values:matches[1].split("','").map(v=>({key:v,value:v}))}}}}}await Promise.all(promise_list);const response=await CN_api.get(`${this.parent_model.module.subject}/${this.parent_model.module.operation.identifier}`);this.#record=await response.json()}show_placeholder(){super.show_placeholder();for(const prop_name in this.#properties){const prop=this.#properties[prop_name];const prop_el=this.element.querySelector(`[name=${prop.id}]`);if(prop.element){if(null==prop_el.querySelector("[name=placeholder]")){prop_el.replaceChild(prop.placeholder_el,prop.element)}}}}hide_placeholder(){super.hide_placeholder();for(const prop_name in this.#properties){const prop=this.#properties[prop_name];const prop_el=this.element.querySelector(`[name=${prop.id}]`);if(prop.element){prop_el.replaceChild(prop.element,prop_el.querySelector("[name=placeholder]"))}}}async on_change(prop_name){const prop=this.#properties[prop_name];const control_el=document.getElementById(prop.id);try{let data={};data[prop_name]=control_el.value;if("boolean"==prop.type){data[prop_name]=""==data[prop_name]?null:Number(data[prop_name])}else if("date"==prop.type){if(""==data[prop_name])data[prop_name]=null}await CN_api.patch(`${this.parent_model.module.subject}/${this.parent_model.module.operation.identifier}`,data);this.#record[prop_name]=data[prop_name]}catch(error){if("Conflict (409)"==error.name){JSON.parse(error.body).forEach(prop_name=>{const prop=this.#properties[prop_name];const prop_el=this.element.querySelector(`[name=${prop.id}]`);const control_el=document.getElementById(prop.id);prop.element.show_error("Conflicts with existing record",5e3)})}else{this.run();throw error}}await this.run()}async on_delete(){const modal=CN_event.modal_confirm({static:true,title:"Please Confirm",message:`
        Are you sure you wish to delete this ${this.parent_model.name.singular}?
      `});if(await modal.test()){await CN_api.delete(`${this.parent_model.module.subject}/${this.parent_model.module.operation.identifier}`);await this.on_navigate_to_parent()}}update_element(){super.update_element();for(const prop_name in this.#properties){const module_prop=this.parent_model.module.properties[prop_name];const prop=this.#properties[prop_name];const control_el=document.getElementById(prop.id);if(null==control_el)return;const prop_el=this.element.querySelector(`[name=${prop.id}]`);if(prop.is_hidden(this)){prop_el.style.display="none"}else{prop_el.style.removeProperty("display")}control_el.disabled=prop.is_constant(this);if(["boolean","enum"].includes(prop.type)){if("boolean"==prop.type){}else if("enum"==prop.type){control_el.innerHTML=module_prop&&module_prop.required?"":`<option value="">(empty)</option>`;prop.enum.values.forEach(option=>{control_el.append(CN_element.create(`
              <option value="${option.key}">${option.value}</option>
            `))})}control_el.querySelectorAll("option").forEach(option_el=>{if(""==option_el.value&&null===this.#record[prop_name]||1==option_el.value&&true===this.#record[prop_name]||0==option_el.value&&false===this.#record[prop_name]||null!=this.#record[prop_name]&&option_el.value===this.#record[prop_name].toString()){option_el.selected=true}else{option_el.removeAttribute("selected")}})}else{control_el.value=null===this.#record[prop_name]?"":this.#record[prop_name];if("text"==prop.type){control_el.style.height="";control_el.style.height=control_el.scrollHeight+"px"}}}}create_property_element(prop_name){const module_prop=this.parent_model.module.properties[prop_name];const prop=this.#properties[prop_name];const prop_el=CN_element.create(`<div name="${prop.id}" class="row mb-3"></div>`);prop_el.append(CN_element.create_form_label({for:prop.id,value:prop.title}));if(!prop.placeholder_el){prop.placeholder_el=CN_element.create(`
        <div name="placeholder" class="col-sm-9 placeholder-glow h-100">
          <input class="form-control placeholder" disabled></input>
        </div>
      `)}if(!prop.element){let params={id:prop.id,name:prop_name,title:prop.title,required:module_prop?module_prop.required:false,placeholder:"(empty)"};if("typeahead"==prop.type){params.typeahead={...prop.typeahead}}else{const self_obj=this;params.onchange=async(control_el,success)=>{if(success){await self_obj.on_change(prop_name)}else{control_el.value=self_obj.record[prop_name]}}}if(["integer","float"].includes(prop.type)){params.min=prop.min;params.max=prop.max}prop.element=CN_element.create_form_element(prop.type,params)}prop_el.append(prop.element);return prop_el}create_body_element(){const form_el=CN_element.create("<form></form>");const fieldset_el=CN_element.create("<fieldset></fieldset>");fieldset_el.disabled=!this.parent_model.allow_edit();form_el.append(fieldset_el);for(const prop_name in this.#properties){fieldset_el.append(this.create_property_element(prop_name))}return form_el}create_footer_element(){const btn_group_el=CN_element.create(`<div class="btn-group" role="group"></div>`);const parent_btn_el=CN_element.create('<button name="back" type="button" class="btn btn-primary">Back</button>');btn_group_el.append(parent_btn_el);(async()=>{parent_btn_el.innerHTML=await this.get_text("view_parent")})();parent_btn_el.onclick=async()=>await this.on_navigate_to_parent();const delete_btn_el=CN_element.create(`
      <button name="delete" type="button" class="btn btn-danger">
        Delete ${CN_common.uc_words(this.parent_model.name.singular)}
      </button>
    `);btn_group_el.append(delete_btn_el);delete_btn_el.onclick=async()=>await this.on_delete();return btn_group_el}render(){const el=super.render();if(1<this.parent_model.module.children.length){const list_selector_el=CN_element.create_card();el.append(list_selector_el);list_selector_el.querySelector(".card-header").append(CN_element.create(`
        <div class="d-flex">
          <div class="flex-grow-1">
            List Selector
          </div>
        </div>
      `));list_selector_el.querySelector(".card-body").remove();const btn_group_el=CN_element.create(`<div class="row"></div>`);list_selector_el.querySelector(".card-footer").append(btn_group_el);this.parent_model.module.children.forEach(child_subject=>{const child_module=CN_session.data.modules[child_subject];const child_btn_el=CN_element.create(`
          <button name="${child_module.subject}" type="button" class="col btn btn-primary mx-1">
            ${CN_common.uc_words(child_module.model.name.singular)}
          </button>
        `);btn_group_el.append(child_btn_el);child_btn_el.onclick=async()=>{this.#tab=child_subject;window.history.replaceState(null,null,`?tab=${this.#tab}`);this.parent_model.module.children.forEach(c=>{let cm=CN_session.data.modules[c];if(c==child_subject){el.append(cm.model.element)}else{cm.model.element.remove()}})};const child_el=child_module.model.render();if(child_subject==new URL(window.location).searchParams.get("tab")){el.append(child_el)}})}else if(1==this.parent_model.module.children.length){el.append(CN_session.data.modules[this.parent_model.module.children[0]].model.render())}return el}async run(children=false){if(!this.parent_model.module.operation)return;await super.run();if(children){this.parent_model.module.children.forEach(async subject=>{const module=CN_session.data.modules[subject];if(module&&"list"==module.operation.action)module.model.run()})}}}
